2	import { attributionAccuracy, tagAccuracy } from "../../src/attribution/evaluate";
3	
4	describe("attributionAccuracy", () => {
5	  test("counts key entries and matches predicted to actual by id", () => {
6	    const pred = [
7	      { id: "a", predicted: "x" },
8	      { id: "b", predicted: "y" },
9	    ];
10	    const key = [
11	      { id: "a", actual: "x" },
12	      { id: "b", actual: "z" },
13	    ];
14	
15	    expect(attributionAccuracy(pred, key)).toEqual({
16	      correct: 1,
17	      total: 2,
18	      accuracy: 0.5,
19	      missing: [],
20	    });
21	  });
22	
23	  test("lists key ids missing from pred as wrong", () => {
24	    const pred = [{ id: "a", predicted: "x" }];
25	    const key = [
26	      { id: "a", actual: "x" },
27	      { id: "b", actual: "y" },
28	      { id: "c", actual: "z" },
29	    ];
30	
31	    expect(attributionAccuracy(pred, key)).toEqual({
32	      correct: 1,
33	      total: 3,
34	      accuracy: 0.3333,
35	      missing: ["b", "c"],
36	    });
37	  });
38	
39	  test("counts a mismatching predicted value as wrong", () => {
40	    const pred = [{ id: "a", predicted: "x" }];
41	    const key = [{ id: "a", actual: "y" }];
42	
43	    expect(attributionAccuracy(pred, key)).toEqual({
44	      correct: 0,
45	      total: 1,
46	      accuracy: 0,
47	      missing: [],
48	    });
49	  });
50	
